    'Complete your subscription and payment setup to access deliveries, shop extras, and billing.' => ['de' => 'Schließe Abo- und Zahlungs-Einrichtung ab, um Lieferungen, Shop-Extras und Abrechnung zu nutzen.', 'en' => 'Complete your subscription and payment setup to access deliveries, shop extras, and billing.', 'fr' => 'Terminez la configuration de l’abonnement et du paiement pour accéder aux livraisons, aux options et à la facturation.'],
    'Complete setup so we can charge your subscription on schedule.' => ['de' => 'Schließe die Einrichtung ab, damit wir dein Abo planmäßig abbuchen können.', 'en' => 'Complete setup so we can charge your subscription on schedule.', 'fr' => 'Terminez la configuration pour que nous puissions prélever votre abonnement à la bonne date.'],
