    'Nach Ablauf der Frist wird Ihre Box für die Lieferung gesperrt.' => ['de' => 'Nach Ablauf der Frist wird Ihre Box für die Lieferung gesperrt.', 'en' => 'After the deadline, your box is locked for delivery.', 'fr' => 'Passé ce délai, votre box est verrouillée pour la livraison.'],
    'Ihre Bestellung wird morgen geliefert.' => ['de' => 'Ihre Bestellung wird morgen geliefert.', 'en' => 'Your order will be delivered tomorrow.', 'fr' => 'Votre commande sera livrée demain.'],
    'Bitte stellen Sie sicher, dass jemand die Lieferung entgegennehmen kann.' => ['de' => 'Bitte stellen Sie sicher, dass jemand die Lieferung entgegennehmen kann.', 'en' => 'Please make sure someone is available to receive the delivery.', 'fr' => 'Merci de vous assurer qu’une personne soit disponible pour recevoir la livraison.'],
    'Ihre letzte Zahlung von :amount :currency konnte leider nicht durchgeführt werden.' => ['de' => 'Ihre letzte Zahlung von :amount :currency konnte leider nicht durchgeführt werden.', 'en' => 'Your last payment of :amount :currency could not be processed.', 'fr' => 'Votre dernier paiement de :amount :currency n’a pas pu être effectué.'],
    'Bitte aktualisieren Sie Ihre Zahlungsmethode, damit Ihre Abo-Lieferung weiterhin erfolgen kann.' => ['de' => 'Bitte aktualisieren Sie Ihre Zahlungsmethode, damit Ihre Abo-Lieferung weiterhin erfolgen kann.', 'en' => 'Please update your payment method so your subscription delivery can continue.', 'fr' => 'Merci de mettre à jour votre moyen de paiement pour que votre livraison d’abonnement puisse continuer.'],
    'Bei Fragen wenden Sie sich gern an uns.' => ['de' => 'Bei Fragen wenden Sie sich gern an uns.', 'en' => 'If you have any questions, we are happy to help.', 'fr' => 'Pour toute question, n’hésitez pas à nous contacter.'],
    'Ihre Zahlung wurde erfolgreich verbucht.' => ['de' => 'Ihre Zahlung wurde erfolgreich verbucht.', 'en' => 'Your payment has been received.', 'fr' => 'Votre paiement a bien été reçu.'],
