    // ---- Marketing about -------------------------------------------------
    'A transparent bridge between Berlin households and regional organic food.' => ['de' => 'Eine transparente Brücke zwischen Berliner Haushalten und regionalen Bio-Lebensmitteln.', 'en' => 'A transparent bridge between Berlin households and regional organic food.', 'fr' => 'Un pont transparent entre les foyers berlinois et l’alimentation bio régionale.'],
    'We make weekly local eating simple: one subscription, clear origins, and fair relationships with the people who grow your food.' => ['de' => 'Wir machen regionales Essen einfach: ein Abo, klare Herkunft und faire Beziehungen zu den Menschen, die dein Essen produzieren.', 'en' => 'We make weekly local eating simple: one subscription, clear origins, and fair relationships with the people who grow your food.', 'fr' => 'Nous simplifions l’alimentation locale hebdomadaire : un abonnement, des origines claires et des relations justes avec celles et ceux qui produisent votre alimentation.'],
    'A simple frustration grew into a clear idea.' => ['de' => 'Aus einem einfachen Frust wurde eine klare Idee.', 'en' => 'A simple frustration grew into a clear idea.', 'fr' => 'Une simple frustration est devenue une idée claire.'],
    'Erdgut grew from a simple frustration: great regional food exists around Berlin, but busy households rarely see who grew it or how value flows back to farms.' => ['de' => 'Erdgut entstand aus einem einfachen Frust: Tolles regionales Essen existiert rund um Berlin, doch viele Haushalte sehen selten, wer es produziert oder wie der Wert zu den Höfen zurückfließt.', 'en' => 'Erdgut grew from a simple frustration: great regional food exists around Berlin, but busy households rarely see who grew it or how value flows back to farms.', 'fr' => 'Erdgut est né d’une frustration simple : de superbes aliments régionaux existent autour de Berlin, mais les foyers occupés voient rarement qui les produit ni comment la valeur revient aux fermes.'],
    "The city's appetite for organic and regional food keeps growing. We focus on connections that stay short, seasonal, and honest." => ['de' => 'Der Appetit der Stadt auf regionale und Bio-Lebensmittel wächst. Wir konzentrieren uns auf kurze, saisonale und ehrliche Verbindungen.', 'en' => "The city's appetite for organic and regional food keeps growing. We focus on connections that stay short, seasonal, and honest.", 'fr' => 'L’appétit de la ville pour les produits bio et régionaux ne cesse de croître. Nous misons sur des liens courts, saisonniers et honnêtes.'],
    'A predictable rhythm helps producers plan harvests and lets you adjust one transparent order instead of juggling many small shops.' => ['de' => 'Ein verlässlicher Rhythmus hilft Erzeugern bei der Ernteplanung und du passt nur eine transparente Bestellung an statt vieler kleiner Einkäufe.', 'en' => 'A predictable rhythm helps producers plan harvests and lets you adjust one transparent order instead of juggling many small shops.', 'fr' => 'Un rythme prévisible aide les producteurs à planifier les récoltes et vous permet d’ajuster une seule commande transparente plutôt que de jongler entre plusieurs petites boutiques.'],
    "A calm subscriber experience: know your next delivery, change your box when it's open, and see the names behind every product." => ['de' => 'Ein ruhiges Erlebnis als Abonnent:in: kenne deine nächste Lieferung, passe deine Box an, wenn sie offen ist, und sieh die Namen hinter jedem Produkt.', 'en' => "A calm subscriber experience: know your next delivery, change your box when it's open, and see the names behind every product.", 'fr' => 'Une expérience d’abonné·e sereine : connaître la prochaine livraison, modifier la box quand elle est ouverte et voir les noms derrière chaque produit.'],
    'Four principles guide every partnership.' => ['de' => 'Vier Prinzipien leiten jede Partnerschaft.', 'en' => 'Four principles guide every partnership.', 'fr' => 'Quatre principes guident chaque partenariat.'],
    'These principles guide how we choose partners and communicate with you.' => ['de' => 'Diese Prinzipien leiten, wie wir Partner auswählen und mit dir kommunizieren.', 'en' => 'These principles guide how we choose partners and communicate with you.', 'fr' => 'Ces principes guident notre choix de partenaires et notre communication avec vous.'],
    'We follow the harvest, not the global year-round aisle.' => ['de' => 'Wir folgen der Ernte, nicht dem globalen Ganzjahres-Regal.', 'en' => 'We follow the harvest, not the global year-round aisle.', 'fr' => 'Nous suivons la récolte, pas le rayon mondial ouvert toute l’année.'],
    'Prioritising producers near Berlin and certified organic where it matters.' => ['de' => 'Wir bevorzugen Erzeuger nahe Berlin und Bio-Zertifizierung, wo es zählt.', 'en' => 'Prioritising producers near Berlin and certified organic where it matters.', 'fr' => 'Priorité aux producteurs proches de Berlin et au bio certifié là où cela compte.'],
    'Every product traces to a named farm or grower you can read about.' => ['de' => 'Jedes Produkt lässt sich einem benannten Hof oder Erzeuger zuordnen, über den du nachlesen kannst.', 'en' => 'Every product traces to a named farm or grower you can read about.', 'fr' => 'Chaque produit renvoie à une ferme ou un producteur nommé que vous pouvez découvrir.'],
    'Pricing and relationships designed so more value stays with producers.' => ['de' => 'Preise und Beziehungen so gestaltet, dass mehr Wert bei den Erzeugern bleibt.', 'en' => 'Pricing and relationships designed so more value stays with producers.', 'fr' => 'Prix et relations pensés pour qu’une plus grande part de la valeur revienne aux producteurs.'],
    'Small team, local partners.' => ['de' => 'Kleines Team, lokale Partner.', 'en' => 'Small team, local partners.', 'fr' => 'Petite équipe, partenaires locaux.'],
    "Erdgut is run by a small crew in Berlin working closely with growers and makers in the region. We're not a faceless marketplace — we're building tools and trust together with the people on your box labels." => ['de' => 'Erdgut wird von einem kleinen Team in Berlin geführt, das eng mit Erzeuger:innen und Handwerker:innen in der Region arbeitet. Wir sind kein gesichtsloser Marktplatz — wir bauen Werkzeuge und Vertrauen gemeinsam mit den Menschen auf deinen Box-Etiketten.', 'en' => "Erdgut is run by a small crew in Berlin working closely with growers and makers in the region. We're not a faceless marketplace — we're building tools and trust together with the people on your box labels.", 'fr' => 'Erdgut est animé par une petite équipe à Berlin, en lien étroit avec les producteur·rice·s et artisan·e·s de la région. Nous ne sommes pas une place de marché anonyme — nous construisons outils et confiance avec les personnes qui figurent sur vos étiquettes de box.'],
    'Short answers to the questions we hear most.' => ['de' => 'Kurze Antworten auf die häufigsten Fragen.', 'en' => 'Short answers to the questions we hear most.', 'fr' => 'Réponses brèves aux questions les plus fréquentes.'],
    'A full FAQ hub may follow later.' => ['de' => 'Eine vollständige FAQ-Seite folgt ggf. später.', 'en' => 'A full FAQ hub may follow later.', 'fr' => 'Une FAQ complète pourra suivre plus tard.'],
    'We focus on Berlin and nearby postcodes. Exact delivery areas evolve as we grow — contact us to check yours.' => ['de' => 'Wir liefern in Berlin und umliegenden Postleitzahlen. Die genauen Liefergebiete entwickeln sich mit uns — schreib uns gern, um deine zu prüfen.', 'en' => 'We focus on Berlin and nearby postcodes. Exact delivery areas evolve as we grow — contact us to check yours.', 'fr' => 'Nous livrons à Berlin et dans les codes postaux proches. Les zones évoluent avec notre croissance — contactez-nous pour vérifier la vôtre.'],
    'Yes. Subscribers can skip or postpone deliveries and adjust preferences from their account when those features are active for your plan.' => ['de' => 'Ja. Abonnent:innen können Lieferungen pausieren oder verschieben und Präferenzen im Konto anpassen, sofern diese Funktionen in deinem Tarif aktiv sind.', 'en' => 'Yes. Subscribers can skip or postpone deliveries and adjust preferences from their account when those features are active for your plan.', 'fr' => 'Oui. Les abonné·e·s peuvent sauter ou reporter des livraisons et modifier leurs préférences depuis leur compte, lorsque ces fonctionnalités sont actives pour leur formule.'],
    'We prioritise organic certification, regional distance, seasonality, and reliability. Every partner is listed with a profile so you can see who supplies your box.' => ['de' => 'Wir achten auf Bio-Zertifizierung, regionale Nähe, Saisonalität und Verlässlichkeit. Jede Partner:in wird mit Profil gelistet, damit du siehst, wer deine Box beliefert.', 'en' => 'We prioritise organic certification, regional distance, seasonality, and reliability. Every partner is listed with a profile so you can see who supplies your box.', 'fr' => 'Nous privilégions la certification bio, la proximité régionale, la saisonnalité et la fiabilité. Chaque partenaire dispose d’un profil pour que vous sachiez qui fournit votre box.'],

    // ---- Marketing contact -----------------------------------------------
    'We’re here to help with subscriptions, deliveries, and partnerships.' => ['de' => 'Wir helfen dir bei Abos, Lieferungen und Partnerschaften.', 'en' => 'We’re here to help with subscriptions, deliveries, and partnerships.', 'fr' => 'Nous sommes là pour les questions d’abonnement, de livraison et de partenariat.'],
    'Send us a note and we’ll get back within about one to two business days. The more context you share, the faster we can help.' => ['de' => 'Schreib uns — wir melden uns in etwa ein bis zwei Werktagen zurück. Je mehr Kontext du teilst, desto schneller können wir helfen.', 'en' => 'Send us a note and we’ll get back within about one to two business days. The more context you share, the faster we can help.', 'fr' => 'Envoyez-nous un message — nous répondons sous un à deux jours ouvrés. Plus vous donnez de contexte, plus nous vous répondons vite.'],
    "We'll be in touch soon." => ['de' => 'Wir melden uns zeitnah.', 'en' => "We'll be in touch soon.", 'fr' => 'Nous vous répondrons bientôt.'],
    'Your message is in our inbox and we’ve logged it for the team.' => ['de' => 'Deine Nachricht liegt in unserem Postfach und wurde fürs Team protokolliert.', 'en' => 'Your message is in our inbox and we’ve logged it for the team.', 'fr' => 'Votre message est dans notre boîte de réception et a été transmis à l’équipe.'],
    'We usually reply within one to two business days.' => ['de' => 'Wir antworten meist innerhalb von ein bis zwei Werktagen.', 'en' => 'We usually reply within one to two business days.', 'fr' => 'Nous répondons généralement sous un à deux jours ouvrés.'],
    'If you don’t see a reply, check your spam or promotions folder.' => ['de' => 'Findest du keine Antwort, prüfe bitte deinen Spam- oder Werbe-Ordner.', 'en' => 'If you don’t see a reply, check your spam or promotions folder.', 'fr' => 'Sans réponse, vérifiez votre dossier spam ou promotions.'],
    'We’ll only use this address to reply to your message.' => ['de' => 'Wir nutzen diese Adresse nur, um auf deine Nachricht zu antworten.', 'en' => 'We’ll only use this address to reply to your message.', 'fr' => 'Nous utiliserons cette adresse uniquement pour répondre à votre message.'],
    'We store your message so our team can respond and improve support. We don’t use it for marketing unless you ask us to.' => ['de' => 'Wir speichern deine Nachricht, damit unser Team antworten und den Support verbessern kann. Wir nutzen sie nicht für Marketing, es sei denn, du wünschst es.', 'en' => 'We store your message so our team can respond and improve support. We don’t use it for marketing unless you ask us to.', 'fr' => 'Nous conservons votre message pour que l’équipe puisse répondre et améliorer le support. Nous ne l’utilisons pas à des fins marketing sauf demande de votre part.'],
    'page.' => ['de' => 'Seite.', 'en' => 'page.', 'fr' => 'page.'],
    'If the form doesn’t go through, wait a minute and try again — we limit rapid submissions to reduce spam.' => ['de' => 'Falls das Formular nicht durchgeht, warte eine Minute und versuche es erneut — wir begrenzen schnelle Einsendungen, um Spam zu reduzieren.', 'en' => 'If the form doesn’t go through, wait a minute and try again — we limit rapid submissions to reduce spam.', 'fr' => 'Si le formulaire ne passe pas, patientez une minute et réessayez — nous limitons les envois rapides pour réduire le spam.'],

    // ---- Marketing home (long phrases) ------------------------------------
    'Fresh weekly boxes from local farms, delivered transparently.' => ['de' => 'Frische Wochenboxen von lokalen Höfen — transparent geliefert.', 'en' => 'Fresh weekly boxes from local farms, delivered transparently.', 'fr' => 'Des box hebdomadaires fraîches des fermes locales, livrées en toute transparence.'],
    'Erdgut connects Berlin households with small-scale producers through a simple subscription. See where your food comes from and support fair pricing for farmers.' => ['de' => 'Erdgut verbindet Berliner Haushalte mit kleinen Erzeugern über ein einfaches Abo. Sieh, woher dein Essen kommt, und unterstütze faire Preise für Landwirt:innen.', 'en' => 'Erdgut connects Berlin households with small-scale producers through a simple subscription. See where your food comes from and support fair pricing for farmers.', 'fr' => 'Erdgut relie les foyers berlinois aux petits producteurs via un abonnement simple. Découvrez d’où vient votre alimentation et soutenez des prix justes pour les agriculteur·rice·s.'],
    'Food from farms and growers near Berlin.' => ['de' => 'Lebensmittel von Höfen und Erzeugern rund um Berlin.', 'en' => 'Food from farms and growers near Berlin.', 'fr' => 'Produits issus de fermes et producteurs proches de Berlin.'],
    'Every product is tied to a named producer.' => ['de' => 'Jedes Produkt ist einem benannten Erzeuger zugeordnet.', 'en' => 'Every product is tied to a named producer.', 'fr' => 'Chaque produit est lié à un producteur identifié.'],
    'Skip, postpone, or adjust when life changes.' => ['de' => 'Pausieren, verschieben oder anpassen, wenn sich das Leben ändert.', 'en' => 'Skip, postpone, or adjust when life changes.', 'fr' => 'Sautez, reportez ou ajustez selon les aléas du quotidien.'],
    'Card handling via SumUp—no card data stored on our servers.' => ['de' => 'Kartenabwicklung über SumUp — keine Kartendaten auf unseren Servern gespeichert.', 'en' => 'Card handling via SumUp—no card data stored on our servers.', 'fr' => 'Paiement par carte via SumUp — aucune donnée de carte stockée sur nos serveurs.'],
    'Vegetables, fruit, bread, dairy, fish and meat — curated weekly.' => ['de' => 'Gemüse, Obst, Brot, Milchprodukte, Fisch und Fleisch — wöchentlich kuratiert.', 'en' => 'Vegetables, fruit, bread, dairy, fish and meat — curated weekly.', 'fr' => 'Légumes, fruits, pain, produits laitiers, poisson et viande — sélection hebdomadaire.'],
    'Each stall is run by producers we know by name. The colours travel with the food from profile to box to invoice.' => ['de' => 'Jeder Stand wird von Erzeuger:innen geführt, die wir beim Namen kennen. Die Farben begleiten die Lebensmittel vom Profil zur Box bis zur Rechnung.', 'en' => 'Each stall is run by producers we know by name. The colours travel with the food from profile to box to invoice.', 'fr' => 'Chaque stand est tenu par des producteurs que nous connaissons par leur nom. Les couleurs accompagnent les produits du profil à la box jusqu’à la facture.'],
    'Try one box before you commit.' => ['de' => 'Probiere eine Box, bevor du dich bindest.', 'en' => 'Try one box before you commit.', 'fr' => 'Testez une box avant de vous engager.'],
    'From signup to your doorstep in four steps.' => ['de' => 'Von der Anmeldung zur Haustür in vier Schritten.', 'en' => 'From signup to your doorstep in four steps.', 'fr' => 'De l’inscription à votre porte en quatre étapes.'],
    'A predictable rhythm that leaves room for the unpredictable parts of your week.' => ['de' => 'Ein verlässlicher Rhythmus, der Platz für das Unvorhergesehene lässt.', 'en' => 'A predictable rhythm that leaves room for the unpredictable parts of your week.', 'fr' => 'Un rythme prévisible qui laisse de la place aux imprévus de la semaine.'],
    'Register and verify your email to get started.' => ['de' => 'Registrieren und E-Mail bestätigen — schon geht’s los.', 'en' => 'Register and verify your email to get started.', 'fr' => 'Inscrivez-vous et vérifiez votre e-mail pour commencer.'],
    'Pick box size and set preferences and dietary notes.' => ['de' => 'Wähle Boxgröße und hinterlege Präferenzen und Diätinfos.', 'en' => 'Pick box size and set preferences and dietary notes.', 'fr' => 'Choisissez la taille de la box et renseignez préférences et notes alimentaires.'],
    'Your box is composed from seasonal, regional produce.' => ['de' => 'Deine Box wird aus saisonalen, regionalen Produkten zusammengestellt.', 'en' => 'Your box is composed from seasonal, regional produce.', 'fr' => 'Votre box est composée de produits de saison et régionaux.'],
    'Change delivery, skip a week, or add extras before the deadline.' => ['de' => 'Lieferung ändern, Woche aussetzen oder Extras hinzufügen — alles vor Ablauf der Frist.', 'en' => 'Change delivery, skip a week, or add extras before the deadline.', 'fr' => 'Modifiez la livraison, sautez une semaine ou ajoutez des suppléments avant la date limite.'],
    'We are onboarding early supporters—real stories and numbers will appear here as the community grows.' => ['de' => 'Wir nehmen gerade die ersten Unterstützer:innen auf — echte Geschichten und Zahlen erscheinen hier, wenn die Community wächst.', 'en' => 'We are onboarding early supporters—real stories and numbers will appear here as the community grows.', 'fr' => 'Nous accueillons les premiers soutiens — de vraies histoires et chiffres apparaîtront ici à mesure que la communauté grandit.'],
    'Products link back to people and places—not anonymous supply chains—so you can trust what lands in your kitchen.' => ['de' => 'Produkte verweisen auf Menschen und Orte — keine anonymen Lieferketten — damit du vertrauen kannst, was in deiner Küche landet.', 'en' => 'Products link back to people and places—not anonymous supply chains—so you can trust what lands in your kitchen.', 'fr' => 'Les produits renvoient à des personnes et à des lieux — non à des chaînes d’approvisionnement anonymes — pour que vous puissiez avoir confiance dans ce qui arrive dans votre cuisine.'],
    'See deadlines, tweak your box when it is editable, and align delivery with your routine.' => ['de' => 'Deadlines einsehen, Box bearbeiten, wenn sie offen ist, und Lieferung an deinen Alltag anpassen.', 'en' => 'See deadlines, tweak your box when it is editable, and align delivery with your routine.', 'fr' => 'Consultez les échéances, ajustez votre box lorsqu’elle est ouverte et calez la livraison sur votre routine.'],
    'We focus on direct relationships and clear value so more of what you pay supports the people who grow your food.' => ['de' => 'Wir setzen auf direkte Beziehungen und klare Werte, damit mehr von dem, was du zahlst, bei den Menschen ankommt, die dein Essen produzieren.', 'en' => 'We focus on direct relationships and clear value so more of what you pay supports the people who grow your food.', 'fr' => 'Nous misons sur des relations directes et une valeur claire afin qu’une plus grande part de ce que vous payez soutienne celles et ceux qui produisent votre alimentation.'],

    // ---- Marketing producers ---------------------------------------------
    'Meet the producers behind your weekly Erdgut box.' => ['de' => 'Lerne die Erzeuger:innen hinter deiner wöchentlichen Erdgut-Box kennen.', 'en' => 'Meet the producers behind your weekly Erdgut box.', 'fr' => 'Rencontrez les producteurs qui composent votre box Erdgut hebdomadaire.'],
    'We partner with farms and small food makers focused on quality, transparency, and fair pricing. Filter by region or search by name—every profile shows where they work and what they stand for.' => ['de' => 'Wir arbeiten mit Höfen und kleinen Lebensmittelmacher:innen zusammen, denen Qualität, Transparenz und faire Preise wichtig sind. Filtere nach Region oder suche nach Name — jedes Profil zeigt, wo sie arbeiten und wofür sie stehen.', 'en' => 'We partner with farms and small food makers focused on quality, transparency, and fair pricing. Filter by region or search by name—every profile shows where they work and what they stand for.', 'fr' => 'Nous collaborons avec des fermes et de petits artisans axés sur la qualité, la transparence et des prix justes. Filtrez par région ou cherchez par nom — chaque profil indique où ils travaillent et ce qu’ils défendent.'],
    'No description yet.' => ['de' => 'Noch keine Beschreibung.', 'en' => 'No description yet.', 'fr' => 'Pas encore de description.'],

    // ---- Onboarding ------------------------------------------------------
    'We will save your details so you can manage deliveries later.' => ['de' => 'Wir speichern deine Angaben, damit du Lieferungen später verwalten kannst.', 'en' => 'We will save your details so you can manage deliveries later.', 'fr' => 'Nous enregistrons vos informations pour que vous puissiez gérer les livraisons plus tard.'],
    'Primary delivery address and gate / floor details so we can find you.' => ['de' => 'Hauptlieferadresse sowie Tor / Etage, damit wir dich finden.', 'en' => 'Primary delivery address and gate / floor details so we can find you.', 'fr' => 'Adresse principale de livraison et infos portail / étage pour qu’on vous trouve.'],
    'Try one box, or sign up for a recurring delivery — you can always switch.' => ['de' => 'Probiere eine Box oder melde dich für regelmäßige Lieferungen an — du kannst jederzeit wechseln.', 'en' => 'Try one box, or sign up for a recurring delivery — you can always switch.', 'fr' => 'Essayez une box ou souscrivez à des livraisons régulières — vous pouvez toujours changer.'],
    'One delivery, no subscription, no auto-renewal.' => ['de' => 'Eine Lieferung, kein Abo, keine automatische Verlängerung.', 'en' => 'One delivery, no subscription, no auto-renewal.', 'fr' => 'Une livraison, sans abonnement, sans renouvellement automatique.'],
    'Weekly or bi-weekly. First box EUR 35, cancel anytime.' => ['de' => 'Wöchentlich oder zweiwöchentlich. Erste Box EUR 35, jederzeit kündbar.', 'en' => 'Weekly or bi-weekly. First box EUR 35, cancel anytime.', 'fr' => 'Hebdomadaire ou bimensuel. Première box 35 EUR, résiliation à tout moment.'],
    'SumUp securely stores a token so we can charge each weekly delivery. We never store the full card number.' => ['de' => 'SumUp speichert sicher ein Token, damit wir jede wöchentliche Lieferung abbuchen können. Die vollständige Kartennummer speichern wir nie.', 'en' => 'SumUp securely stores a token so we can charge each weekly delivery. We never store the full card number.', 'fr' => 'SumUp conserve un jeton sécurisé pour que nous puissions prélever chaque livraison hebdomadaire. Nous ne stockons jamais le numéro complet de la carte.'],
    'Payment did not go through. Please check your card details and try again — no charge has been made.' => ['de' => 'Die Zahlung konnte nicht abgeschlossen werden. Bitte prüfe deine Kartendaten und versuche es erneut — es wurde nichts abgebucht.', 'en' => 'Payment did not go through. Please check your card details and try again — no charge has been made.', 'fr' => 'Le paiement n’a pas abouti. Merci de vérifier vos informations de carte et de réessayer — aucun débit n’a été effectué.'],
    'You can pause, skip, or cancel from your dashboard at any time.' => ['de' => 'Du kannst jederzeit über dein Dashboard pausieren, aussetzen oder kündigen.', 'en' => 'You can pause, skip, or cancel from your dashboard at any time.', 'fr' => 'Vous pouvez mettre en pause, sauter ou annuler à tout moment depuis votre tableau de bord.'],
    'Your trial box is booked. We will email you the delivery date shortly.' => ['de' => 'Deine Testbox ist gebucht. Das Lieferdatum senden wir dir in Kürze per E-Mail.', 'en' => 'Your trial box is booked. We will email you the delivery date shortly.', 'fr' => 'Votre box d’essai est réservée. Nous vous enverrons la date de livraison par e-mail sous peu.'],
    'We schedule trial deliveries manually. We will confirm your exact date within :days days.' => ['de' => 'Testlieferungen planen wir manuell. Wir bestätigen dir das genaue Datum innerhalb von :days Tagen.', 'en' => 'We schedule trial deliveries manually. We will confirm your exact date within :days days.', 'fr' => 'Nous planifions les livraisons d’essai manuellement. Nous confirmerons la date exacte sous :days jours.'],
    'One-time charge of EUR :amount. No subscription, no stored card.' => ['de' => 'Einmalige Zahlung von EUR :amount. Kein Abo, keine gespeicherte Karte.', 'en' => 'One-time charge of EUR :amount. No subscription, no stored card.', 'fr' => 'Paiement unique de :amount EUR. Pas d’abonnement, pas de carte enregistrée.'],

    // ---- Products / shop -------------------------------------------------
    'Five stalls, curated weekly.' => ['de' => 'Fünf Stände, wöchentlich kuratiert.', 'en' => 'Five stalls, curated weekly.', 'fr' => 'Cinq stands, sélection hebdomadaire.'],
    'Check back soon — new products are added each week.' => ['de' => 'Schau bald wieder vorbei — jede Woche kommen neue Produkte dazu.', 'en' => 'Check back soon — new products are added each week.', 'fr' => 'Revenez bientôt — de nouveaux produits sont ajoutés chaque semaine.'],

    // ---- Profile ---------------------------------------------------------
    'Once your account is deleted, all of its resources and data will be permanently deleted. Before deleting your account, please download any data or information that you wish to retain.' => ['de' => 'Nach dem Löschen deines Kontos werden alle Daten dauerhaft entfernt. Lade dir vor dem Löschen alle Informationen herunter, die du behalten möchtest.', 'en' => 'Once your account is deleted, all of its resources and data will be permanently deleted. Before deleting your account, please download any data or information that you wish to retain.', 'fr' => 'Une fois votre compte supprimé, toutes ses ressources et données seront effacées définitivement. Avant la suppression, téléchargez les informations que vous souhaitez conserver.'],
    'Once your account is deleted, all of its resources and data will be permanently deleted. Please enter your password to confirm you would like to permanently delete your account.' => ['de' => 'Nach dem Löschen deines Kontos werden alle Daten dauerhaft entfernt. Bitte gib dein Passwort ein, um die endgültige Löschung zu bestätigen.', 'en' => 'Once your account is deleted, all of its resources and data will be permanently deleted. Please enter your password to confirm you would like to permanently delete your account.', 'fr' => 'Une fois votre compte supprimé, toutes les ressources et données seront effacées définitivement. Saisissez votre mot de passe pour confirmer la suppression définitive.'],

    // ---- Admin controller flash messages ---------------------------------
    'Producer created.' => ['de' => 'Erzeuger angelegt.',   'en' => 'Producer created.',     'fr' => 'Producteur créé.'],
    'Producer updated.' => ['de' => 'Erzeuger aktualisiert.', 'en' => 'Producer updated.',    'fr' => 'Producteur mis à jour.'],
    'This producer cannot be deleted while products are still assigned. Reassign or delete those products first.' => ['de' => 'Dieser Erzeuger kann nicht gelöscht werden, solange Produkte zugeordnet sind. Weise sie einem anderen Erzeuger zu oder lösche sie zuerst.', 'en' => 'This producer cannot be deleted while products are still assigned. Reassign or delete those products first.', 'fr' => 'Ce producteur ne peut pas être supprimé tant que des produits lui sont rattachés. Réaffectez-les ou supprimez-les d’abord.'],
    'Producer deleted.' => ['de' => 'Erzeuger gelöscht.',  'en' => 'Producer deleted.',    'fr' => 'Producteur supprimé.'],
    'Product created.' => ['de' => 'Produkt angelegt.',    'en' => 'Product created.',     'fr' => 'Produit créé.'],
    'Product updated.' => ['de' => 'Produkt aktualisiert.', 'en' => 'Product updated.',    'fr' => 'Produit mis à jour.'],
    'This product cannot be deleted because it appears on one or more boxes.' => ['de' => 'Dieses Produkt kann nicht gelöscht werden, weil es in einer oder mehreren Boxen verwendet wird.', 'en' => 'This product cannot be deleted because it appears on one or more boxes.', 'fr' => 'Ce produit ne peut pas être supprimé car il apparaît dans une ou plusieurs box.'],
    'Product deleted.' => ['de' => 'Produkt gelöscht.',   'en' => 'Product deleted.',     'fr' => 'Produit supprimé.'],
    'The selected product is not available.' => ['de' => 'Das ausgewählte Produkt ist nicht verfügbar.', 'en' => 'The selected product is not available.', 'fr' => 'Le produit sélectionné n’est pas disponible.'],
];
